var p=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerController>();var e=p.visual.GetComponent<Bulldozer.Player.MinerEquipment>();var u=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerUpgradeArea>();p.autoMine=false;p.CancelMining();
